/* ── One error rule for every control that can be invalid ───────────────── */
/* Fields (inside the machined frame): hatching + tarnish. */
[data-material="metallic"] :is([data-slot="input"], [data-slot="textarea"], [data-slot="select-trigger"], [data-slot="native-select"])[aria-invalid="true"], [data-material="metallic"] [data-slot="input-group"]:has([aria-invalid="true"]) {
  background: var(--metallic-hatch), var(--metallic-tarnish-fill), var(--metallic-field-frame) border-box;
