/* Small parts (OTP slots, checkbox, radio, switch): a strip won't fit, so always the fine hatch. */
[data-material="metallic"] :is([data-slot="input-otp-slot"], [data-slot="checkbox"], [data-slot="radio-group-item"], [data-slot="switch"])[aria-invalid="true"] {
