/* ── Table: a machined panel ──────────────────────────────────────────────── */
/*
 * Chrome paints a row's background cell by cell, which leaves hairline seams at fractional column edges. So the
 * header strip is painted once on the panel, sized to the header row (2.5rem), and row tints go on the cells.
 * Size and repeat lists cover the longest layer stack (strip 2 + textured panel 3).
 */
[data-material="metallic"] [data-slot="table-container"] {
  border: 1px solid var(--metallic-edge-quiet);
  border-radius: var(--radius-lg);
  background-image: var(--metallic-strip), var(--metallic-panel);
  background-size: 100% 2.5rem, 100% 2.5rem, auto, auto, auto;
  background-repeat: no-repeat, no-repeat, repeat, repeat, repeat;
  box-shadow: inset 0 1px 0 var(--metallic-chamfer), 0 1px 2px rgba(0,0,0,.08);
  --muted-foreground: var(--metallic-panel-muted);
}
/* Header: a steel strip with engraved column names. */
[data-material="metallic"] [data-slot="table-header"] [data-slot="table-row"] {
  background: none;
  border-bottom: 1px solid color-mix(in oklch, var(--metallic-edge) 55%, transparent);
}
[data-material="metallic"] [data-slot="table-header"] [data-slot="table-head"] { box-shadow: inset 0 1px 0 rgba(255,255,255,.75); }
:is([data-material="metallic"].dark, .dark [data-material="metallic"]) [data-slot="table-header"] [data-slot="table-head"] { box-shadow: inset 0 1px 0 rgba(255,255,255,.06); }
