[data-material="metallic"] [data-slot="table-body"] [data-slot="table-row"] { border-bottom-color: color-mix(in oklch, var(--metallic-edge-quiet) 55%, transparent); }
[data-material="metallic"] [data-slot="table-body"] [data-slot="table-row"] > [data-slot="table-cell"] { box-shadow: inset 0 -1px 0 var(--metallic-seam-light); }
[data-material="metallic"] [data-slot="table-body"] [data-slot="table-row"]:last-child { border-bottom: 0; }
[data-material="metallic"] [data-slot="table-body"] [data-slot="table-row"]:is(:hover, [data-state="selected"]) { background: none; }
/*
 * Hover (round 7): the tint and a thin steel edge come up quickly and drain away slowly, so moving down a table
 * leaves a short fading trail. Leaving uses the base transition (slow); arriving uses the :hover one (fast).
