[data-material="metallic"] [data-slot="table-body"] [data-slot="table-row"]:not([data-state="selected"]):hover > [data-slot="table-cell"]:first-child { box-shadow: inset 2px 0 0 color-mix(in oklch, var(--metallic-edge) 70%, transparent), inset 0 -1px 0 var(--metallic-seam-light); }
