/* Polish: how reflective the steel is (band contrast and sweep strength). Dark Mirror's top band is held at AA for its ink. */
[data-material="metallic"][data-polish="satin"] {
  --metallic-steel-base: linear-gradient(180deg, color-mix(in oklch, #eef1f5, var(--alloy-c) var(--alloy-k)) 0%, color-mix(in oklch, #dfe3e9, var(--alloy-c) var(--alloy-k)) 34%, color-mix(in oklch, #c4c9d1, var(--alloy-c) var(--alloy-k)) 52%, color-mix(in oklch, #d5d9df, var(--alloy-c) var(--alloy-k)) 76%, color-mix(in oklch, #eaedf1, var(--alloy-c) var(--alloy-k)) 100%);
