}
:is([data-material="metallic"].dark, .dark [data-material="metallic"])[data-polish="mirror"] { --metallic-steel-base: linear-gradient(180deg, color-mix(in oklch, #606774, var(--alloy-c) var(--alloy-k)) 0%, color-mix(in oklch, #3b414a, var(--alloy-c) var(--alloy-k)) 30%, color-mix(in oklch, #191c21, var(--alloy-c) var(--alloy-k)) 50%, color-mix(in oklch, #2c3138, var(--alloy-c) var(--alloy-k)) 72%, color-mix(in oklch, #5a616d, var(--alloy-c) var(--alloy-k)) 100%); }
/*
 * Alloy: twelve distinct metals. Steel is the original (exact hex bands above). Every other alloy builds its plate
 * from oklch bands: lightness comes from Polish (and the page mode), hue and chroma from the alloy, plus an optional
 * flatten (matte metals) and lift (brighter or darker metals). Light mode = lighter metal with dark ink; dark mode =
 * deep anodized metal with light ink. All 72 alloy x polish x mode plates keep the ink at 4.9:1 or better.
 * Large surfaces only get a faint hint of the alloy (--alloy-k), so a red theme never turns the page red.
