:is([data-material="metallic"].dark, .dark [data-material="metallic"])[data-polish="mirror"] { --band-1: .50; --band-2: .38; --band-3: .26; --band-4: .34; --band-5: .49; }

[data-material="metallic"][data-alloy="silver"] { --alloy-h: 90; --alloy-cc: 0.004; --alloy-flat: 1; --alloy-lift: 0.03; --alloy-k: 10%; }
