[data-material="metallic"][data-alloy="blue"] { --alloy-h: 255; --alloy-cc: 0.11; --alloy-flat: 1; --alloy-lift: 0; --alloy-k: 7%; }
[data-material="metallic"][data-alloy="red"] { --alloy-h: 22; --alloy-cc: 0.13; --alloy-flat: 1; --alloy-lift: 0; --alloy-k: 7%; }
