  --metallic-grain-panel: repeating-linear-gradient(180deg, rgba(255,255,255,.55) 0 2px, transparent 2px 5px), repeating-linear-gradient(180deg, rgba(0,0,0,.045) 0 1px, transparent 1px 9px);
  --metallic-grain-tray: repeating-linear-gradient(180deg, rgba(255,255,255,.45) 0 2px, transparent 2px 5px);
