/* Collapsing is a panel opening: the height family, never a bounce. */
[data-material="metallic"] :is([data-slot="sidebar-gap"], [data-slot="sidebar-container"]) { transition-duration: var(--motion-height); transition-timing-function: var(--ease-height); }
[data-material="metallic"] [data-slot="sidebar-rail"]::after { transition: background-color var(--motion-fast) var(--ease-standard); }
[data-material="metallic"] [data-slot="sidebar-inset"] { background: var(--background); }

/* ── Drawer: brushed panel body, steel grip, tray footer; height family, no bounce ── */
[data-material="metallic"] [data-vaul-drawer] { transition-duration: calc(var(--motion-height) * 1.15); transition-timing-function: var(--ease-height); }
[data-material="metallic"] [data-slot="drawer-overlay"] { transition-duration: calc(var(--motion-height) * 1.15); transition-timing-function: var(--ease-height); }
[data-material="metallic"] [data-slot="drawer-content"] > div:first-child:not([data-slot]) {
  background: var(--metallic-steel);
  box-shadow: var(--metallic-depth-raised-flush), 0 0 0 1px var(--metallic-edge);
}
/* Footer stays tray — deliberately different from the panel body. */
[data-material="metallic"] [data-slot="drawer-footer"] { background: var(--metallic-tray); border-top: 1px solid color-mix(in oklch, var(--metallic-edge) 45%, transparent); box-shadow: inset 0 1px 0 var(--metallic-seam-light); }
[data-material="metallic"] :is([data-slot="drawer-title"]) { text-shadow: var(--metallic-surface-engrave); }

/* ── Scroll area: a satin steel thumb in a faint groove ── */
[data-material="metallic"] [data-slot="scroll-area-scrollbar"] { box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--metallic-edge-quiet) 50%, transparent); background: color-mix(in oklch, var(--metallic-edge) 6%, transparent); }
[data-material="metallic"] [data-slot="scroll-area-thumb"] {
  background: var(--metallic-satin);
  box-shadow: inset 0 0 0 1px var(--metallic-edge), var(--metallic-depth-satin);
  transition: filter var(--motion-fast) var(--ease-standard);
}
@media (hover: hover) { [data-material="metallic"] [data-slot="scroll-area-thumb"]:hover { filter: brightness(.96); } }

/* ── Resizable: a machined seam with a steel grip that presses in while it is held ── */
[data-material="metallic"] [data-slot="resizable-handle"] { background: var(--metallic-edge-quiet); box-shadow: 1px 0 0 var(--metallic-seam-light); }
[data-material="metallic"] [data-slot="resizable-handle"][aria-orientation="horizontal"] { box-shadow: 0 1px 0 var(--metallic-seam-light); }
[data-material="metallic"] [data-slot="resizable-handle"] > div {
  background: var(--metallic-steel);
  box-shadow: var(--metallic-depth-raised-flush), inset 0 0 0 1px var(--metallic-edge);
  transition: scale var(--motion-pop) var(--ease-pop), filter var(--motion-fast) var(--ease-standard);
}
[data-material="metallic"] [data-slot="resizable-handle"]:is(:hover, [data-separator="active"], :focus-visible) > div { filter: brightness(1.04); }
[data-material="metallic"] [data-slot="resizable-handle"][data-separator="active"] > div { scale: .88; box-shadow: var(--metallic-depth-pressed), inset 0 0 0 1px var(--metallic-edge); }

/* ── Native select: a field groove; Combobox rides on Input Group and the Command list already ── */
/* The field rules reset the padding, so the room for the chevron is set again here (it sits 10px from the right edge). */
[data-material="metallic"] [data-slot="native-select"] { padding-inline: 12px 2.25rem; text-overflow: ellipsis; }
[data-material="metallic"] [data-slot="native-select-icon"] { color: var(--muted-foreground); right: 12px; }

/* ── Item, Empty: the panel's own rim; media become steel beads and engraved wells ── */
/* Item is a row that normally sits inside a card or panel, so its default is transparent. The two surfaced variants get metal. */
[data-material="metallic"] [data-slot="item"][data-variant="outline"] {
  border-color: var(--metallic-edge-quiet);
  background: var(--metallic-panel);
  box-shadow: var(--metallic-depth-satin);
  --muted-foreground: var(--metallic-panel-muted);
}
[data-material="metallic"] [data-slot="item"][data-variant="muted"] {
  background: var(--metallic-tray);
  border-color: var(--metallic-edge-quiet);
  box-shadow: inset 0 1px 3px rgba(0,0,0,.14), 0 1px 0 var(--metallic-seam-light);
  --muted-foreground: var(--metallic-panel-muted);
}
[data-material="metallic"] [data-slot="item-title"] { text-shadow: var(--metallic-surface-engrave); }
[data-material="metallic"] [data-slot="item"] { transition: background-color calc(240ms * var(--motion-scale)) var(--ease-standard); }
[data-material="metallic"] [data-slot="item-separator"] { background: var(--metallic-edge-quiet); box-shadow: 0 1px 0 var(--metallic-seam-light); }
[data-material="metallic"] [data-slot="item-media"][data-variant="icon"] {
  /* This version of Item gives the icon no box of its own, so the bead is made here: a 32px steel disc. */
  box-sizing: border-box;
  width: 2rem;
  height: 2rem;
  border-radius: var(--radius-md);
  background: var(--metallic-steel);
  color: var(--metallic-ink);
  border: 1px solid var(--metallic-edge);
  box-shadow: var(--metallic-depth-raised-flush);
}
/* Empty is a placeholder well: a brushed panel with a soft inset edge, so an empty list still reads as a surface. */
[data-material="metallic"] [data-slot="empty"] {
  background: var(--metallic-panel);
  border-color: var(--metallic-edge-quiet);
  box-shadow: inset 0 1px 3px rgba(0,0,0,.1), 0 1px 0 var(--metallic-seam-light);
  --muted-foreground: var(--metallic-panel-muted);
}
[data-material="metallic"] [data-slot="empty-title"] { text-shadow: var(--metallic-surface-engrave); }
[data-material="metallic"] [data-slot="empty-icon"] {
  background: var(--metallic-glass);
  border: 1px solid var(--metallic-edge);
  box-shadow: var(--metallic-depth-groove);
  color: var(--muted-foreground);
}

/* ── Avatar: a steel ring, engraved initials; groups overlap less so the initials are never clipped ── */
[data-material="metallic"] [data-slot="avatar"] { box-shadow: 0 0 0 1px var(--metallic-edge); }
[data-material="metallic"] [data-slot="avatar-fallback"] {
  background: var(--metallic-steel);
  color: var(--metallic-ink);
  box-shadow: var(--metallic-depth-raised-flush);
  font-size: 12px;
  font-weight: 500;
  text-shadow: var(--metallic-engrave);
}
[data-material="metallic"] [data-slot="avatar-group"] > * { margin-inline-end: 0; }
[data-material="metallic"] [data-slot="avatar-group"] > * + * { margin-inline-start: -.375rem; }

/* ── Alert: a callout sits straight on the page, so it is a brushed tray with an engraved title (status stays icon plus words) ── */
[data-material="metallic"] [data-slot="alert"] {
  background: var(--metallic-tray);
  border-color: var(--metallic-edge-quiet);
  color: var(--metallic-tray-ink);
  box-shadow: var(--metallic-depth-satin);
  --muted-foreground: var(--metallic-panel-muted);
}
[data-material="metallic"] [data-slot="alert-title"] { text-shadow: var(--metallic-surface-engrave); }
/* shadcn's Alert does not put its variant on the element, but its destructive variant does carry the text-destructive class,
   so the rules below read either signal: data-variant="destructive" (custom alerts) or that class (stock alert, no edits).
   The description's colour is set explicitly (the stock red at 90% opacity fails contrast on the tray). */
[data-material="metallic"] [data-slot="alert-description"] { color: var(--metallic-panel-muted); }
[data-material="metallic"] [data-slot="alert"]:is([data-variant="destructive"], .text-destructive) { color: var(--metallic-danger-ink); border-color: var(--metallic-danger-ink); }
[data-material="metallic"] [data-slot="alert"]:is([data-variant="destructive"], .text-destructive) [data-slot="alert-description"] { color: var(--metallic-danger-ink); }

/* ── Tooltip: a small dark steel tag (bright steel in dark mode), so it reads as a label pinned to the part ── */
[data-material="metallic"] [data-slot="tooltip-content"] {
  --metallic-tag: linear-gradient(180deg, #4a505b 0%, #2c3038 100%);
  --metallic-tag-ink: #f2f4f7;
  --metallic-tag-edge: #1c2028;
  --metallic-tag-end: #2c3038;
  --metallic-tag-lip: rgba(255,255,255,.18);
  background: var(--metallic-tag);
  color: var(--metallic-tag-ink);
  border: 1px solid var(--metallic-tag-edge);
  box-shadow: inset 0 1px 0 var(--metallic-tag-lip), 0 2px 6px rgba(0,0,0,.28);
  text-shadow: 0 -1px 0 rgba(0,0,0,.45);
}
:is([data-material="metallic"].dark, .dark [data-material="metallic"]) [data-slot="tooltip-content"] {
  --metallic-tag: linear-gradient(180deg, #f5f7fb 0%, #c4c9d3 100%);
  --metallic-tag-ink: #1c2028;
  --metallic-tag-edge: #6b717d;
  --metallic-tag-end: #c4c9d3;
  --metallic-tag-lip: rgba(255,255,255,.9);
  text-shadow: 0 1px 0 rgba(255,255,255,.6);
}
/* The little arrow takes the tag's bottom colour so the join disappears. */
[data-material="metallic"] [data-slot="tooltip-content"] svg:not([data-slot="kbd"] svg) { background: var(--metallic-tag-end); fill: var(--metallic-tag-end); }
/* The doubled attribute outranks the shared satin rule that every kbd gets. */
[data-material="metallic"] [data-slot="tooltip-content"][data-slot] [data-slot="kbd"] { background: color-mix(in oklch, var(--metallic-tag-ink) 14%, transparent); border-color: transparent; box-shadow: none; color: var(--metallic-tag-ink); }

/* ── Breadcrumb: links are quiet engraved text, the current page is cut deeper, separators are grooves ── */
[data-material="metallic"] [data-slot="breadcrumb-link"] { color: var(--muted-foreground); text-shadow: var(--metallic-engrave); }
@media (hover: hover) {
  [data-material="metallic"] [data-slot="breadcrumb-link"]:hover { color: var(--foreground); }
}
[data-material="metallic"] [data-slot="breadcrumb-page"] { color: var(--foreground); font-weight: 500; text-shadow: var(--metallic-engrave); }
[data-material="metallic"] [data-slot="breadcrumb-separator"] { color: var(--metallic-edge-quiet); }
[data-material="metallic"] [data-slot="breadcrumb-separator"] svg { filter: drop-shadow(0 1px 0 var(--metallic-seam-light)); }
[data-material="metallic"] [data-slot="breadcrumb-ellipsis"] {
  background: var(--metallic-satin);
  border: 1px solid var(--metallic-edge-quiet);
  border-radius: calc(var(--radius, .625rem) - 2px);
  box-shadow: var(--metallic-depth-satin);
  color: var(--muted-foreground);
}

/* ── Label: engraved like the other titles; the wording stays sentence case so forms read normally ── */
[data-material="metallic"] :is([data-slot="label"], [data-slot="field-label"]) { text-shadow: var(--metallic-engrave); }

/* ── Chart: the series are steel and the current alloy, labels are engraved small caps ── */
[data-material="metallic"] {
  --chart-1: color-mix(in oklch, var(--metallic-edge), black 28%);
  --chart-2: var(--metallic-edge);
  --chart-3: color-mix(in oklch, var(--metallic-edge), white 28%);
  --chart-4: color-mix(in oklch, var(--metallic-edge), black 48%);
  --chart-5: color-mix(in oklch, var(--metallic-edge), white 50%);
}
:is([data-material="metallic"].dark, .dark [data-material="metallic"]) {
  --chart-1: color-mix(in oklch, var(--metallic-edge), white 32%);
  --chart-2: var(--metallic-edge);
  --chart-3: color-mix(in oklch, var(--metallic-edge), black 25%);
  --chart-4: color-mix(in oklch, var(--metallic-edge), white 55%);
  --chart-5: color-mix(in oklch, var(--metallic-edge), black 45%);
}
[data-material="metallic"] [data-slot="chart"] .recharts-cartesian-axis-tick text { font: 500 11px/16px var(--font-mono, ui-monospace, monospace); letter-spacing: .04em; text-transform: uppercase; fill: var(--muted-foreground); }
[data-material="metallic"] [data-slot="chart"] .recharts-cartesian-grid line { stroke: var(--metallic-edge-quiet); stroke-opacity: .45; }
[data-material="metallic"] [data-slot="chart"] .recharts-tooltip-wrapper > div {
  border: 2px solid transparent;
  background: var(--metallic-panel) padding-box, var(--metallic-steel) border-box;
  box-shadow: var(--metallic-panel-depth);
  color: var(--popover-foreground);
  --muted-foreground: var(--metallic-panel-muted);
}

/* ══ AI chat items ══ */
/* Your message is a light steel plate (the approved chat rule); other bubbles are quiet surfaces. */
[data-material="metallic"] [data-slot="bubble"][data-variant="default"] > [data-slot="bubble-content"] {
  background: var(--metallic-strip);
  color: var(--metallic-strip-ink);
  box-shadow: var(--metallic-depth-raised-flush), inset 0 0 0 1px var(--metallic-edge), 0 1px 2px rgba(0,0,0,.18);
}
[data-material="metallic"] [data-slot="bubble"][data-variant="secondary"] > [data-slot="bubble-content"] { background: var(--metallic-satin); color: var(--foreground); box-shadow: var(--metallic-depth-satin), inset 0 0 0 1px var(--metallic-edge-quiet); }
[data-material="metallic"] [data-slot="bubble"]:is([data-variant="muted"], [data-variant="tinted"]) > [data-slot="bubble-content"] { background: var(--metallic-tray); color: var(--metallic-tray-ink); box-shadow: inset 0 0 0 1px var(--metallic-edge-quiet); }
[data-material="metallic"] [data-slot="bubble"][data-variant="outline"] > [data-slot="bubble-content"] { border-color: var(--metallic-edge-quiet); background: var(--background); }
[data-material="metallic"] [data-slot="bubble-reactions"] { background: var(--metallic-satin); box-shadow: inset 0 0 0 1px var(--metallic-edge-quiet); }
/* Attachments are machined chips. */
[data-material="metallic"] [data-slot="attachment"] {
  background: var(--metallic-tray);
  border-color: var(--metallic-edge-quiet);
  color: var(--metallic-tray-ink);
  box-shadow: var(--metallic-depth-satin);
  --muted-foreground: var(--metallic-panel-muted);
}
[data-material="metallic"] [data-slot="attachment-media"] { background: var(--metallic-glass); box-shadow: var(--metallic-depth-groove); border: 1px solid var(--metallic-edge-quiet); }
/* While a file is still being sent the name keeps its colour; stock draws a text shimmer, which would read as the steel sheen. */
[data-material="metallic"] [data-slot="attachment-title"] { color: inherit; opacity: 1; animation: none; background: none; -webkit-text-fill-color: currentColor; }
/* Markers are engraved labels on a machined seam. */
[data-material="metallic"] [data-slot="marker"] { color: var(--muted-foreground); }
[data-material="metallic"] [data-slot="marker"][data-variant="separator"] [data-slot="marker-content"] { font: 500 12px/16px var(--font-mono, ui-monospace, monospace); letter-spacing: .06em; text-transform: uppercase; }
[data-material="metallic"] [data-slot="marker"][data-variant="separator"]::before, [data-material="metallic"] [data-slot="marker"][data-variant="separator"]::after { background: var(--metallic-edge-quiet); box-shadow: 0 1px 0 var(--metallic-seam-light); }
[data-material="metallic"] [data-slot="marker"][data-variant="border"] { border-bottom-color: var(--metallic-edge-quiet); box-shadow: 0 1px 0 var(--metallic-seam-light); }
/* Trace: status lamps. Running is the busy lamp, an error keeps the danger ink, and the words stay beside both. */
[data-material="metallic"] :is([data-slot="trace-line"], [data-slot="trace-collapsible-trigger"]) { color: var(--metallic-panel-muted); }
@media (hover: hover) { [data-material="metallic"] :is(a, button):is([data-slot="trace-line"], [data-slot="trace-collapsible-trigger"]):hover, [data-material="metallic"] :is(a, button):hover > [data-slot="trace-line"] { color: var(--foreground); } }
[data-material="metallic"] [data-slot="trace-line"][data-status="error"] { color: var(--metallic-danger-ink); }
[data-material="metallic"] [data-slot="trace-title"] { color: inherit; opacity: 1; animation: none; background: none; -webkit-text-fill-color: currentColor; }
[data-material="metallic"] [data-slot="trace"] { --muted-foreground: var(--metallic-panel-muted); }
[data-material="metallic"] [data-slot="trace-description"] { color: var(--metallic-panel-muted); }
[data-material="metallic"] [data-slot="trace-line"]:is([data-status="running"], [data-status="pending"]) [data-slot="trace-icon"] { position: relative; }
[data-material="metallic"] [data-slot="trace-line"][data-status="running"] [data-slot="trace-icon"]::after {
  content: "";
  position: absolute;
  inset: -3px -3px auto auto;
  width: 7px; height: 7px;
  border-radius: 999px;
  background: #d99a1e;
  box-shadow: 0 0 0 1px rgba(0,0,0,.25), inset 0 1px 0 rgba(255,255,255,.5), 0 0 6px rgba(217,154,30,.65);
  animation: metallic-led calc(1200ms * var(--motion-scale, 1)) ease-in-out infinite;
}
[data-material="metallic"] [data-slot="trace-collapsible-content-inner"] { border-left-color: var(--metallic-edge-quiet); box-shadow: -1px 0 0 var(--metallic-seam-light); }
[data-material="metallic"] [data-slot="trace-collapsible-content"] { animation-duration: var(--motion-height); animation-timing-function: var(--ease-height); }
[data-material="metallic"] [data-slot="trace-collapsible-trigger"] > [data-slot="trace-icon"] { transition: rotate var(--motion-travel) var(--ease-travel); }
/* Code block: an engraved header over a recessed glass window; syntax colours were chosen for a light window. */
[data-material="metallic"] [data-slot="code-block"] {
  border: 1px solid var(--metallic-edge-quiet);
  background: var(--metallic-tray);
  color: var(--foreground);
  box-shadow: var(--metallic-depth-satin);
  --muted-foreground: var(--metallic-panel-muted);
}
/* The header is a real bar: centred content, room below it before the window starts, and the copy icon is a button. */
[data-material="metallic"] [data-slot="code-block-header"] { text-shadow: var(--metallic-surface-engrave); align-items: center; min-height: 2.75rem; padding: .5rem .5rem .5rem .75rem; }
/* The stock actions group is pulled 6px toward the edge (-mr-1.5); the button sits an even 8px from the top, right and bottom instead. */
[data-material="metallic"] [data-slot="code-block-actions"] { margin-block: 0; margin-inline-end: 0; }
[data-material="metallic"] [data-slot="code-block-content"] { margin-inline: .375rem; margin-bottom: .375rem; }
[data-material="metallic"] [data-slot="code-block-copy-button"] {
  width: 1.75rem;
  height: 1.75rem;
  background: var(--metallic-satin);
  border: 1px solid var(--metallic-edge-quiet);
  box-shadow: var(--metallic-depth-satin);
  color: var(--foreground);
  text-shadow: none;
}
[data-material="metallic"] [data-slot="code-block-title"] { font: 500 12px/16px var(--font-mono, ui-monospace, monospace); letter-spacing: .06em; text-transform: uppercase; }
[data-material="metallic"] [data-slot="code-block-content"] { background: var(--metallic-glass); box-shadow: var(--metallic-depth-groove); border-radius: var(--radius-md); }
/* Questionnaire: unticked choices are recessed glass, the chosen one turns to steel (steel means on). */
[data-material="metallic"] [data-slot="questionnaire-choice"] {
  background: var(--metallic-glass);
  border-color: var(--metallic-edge-quiet);
  box-shadow: var(--metallic-depth-groove);
  transition: background-color var(--motion-fast) var(--ease-standard), border-color var(--motion-fast) var(--ease-standard), box-shadow var(--motion-fast) var(--ease-standard);
}
@media (hover: hover) { [data-material="metallic"] [data-slot="questionnaire-choice"]:hover { border-color: var(--metallic-edge-hover); } }
[data-material="metallic"] [data-slot="questionnaire-choice"]:has([data-slot="questionnaire-choice-input"]:checked) {
  background: var(--metallic-steel);
  border-color: var(--metallic-edge);
  color: var(--metallic-ink);
  box-shadow: var(--metallic-depth-raised-flush);
  --muted-foreground: color-mix(in oklch, var(--metallic-ink) 78%, transparent);
}
[data-material="metallic"] [data-slot="questionnaire-choice-indicator"] { border-color: var(--metallic-edge); background: var(--metallic-glass); box-shadow: var(--metallic-depth-groove); }
[data-material="metallic"] [data-slot="questionnaire-choice"]:has([data-slot="questionnaire-choice-input"]:checked) [data-slot="questionnaire-choice-indicator"] { background: transparent; border-color: var(--metallic-ink); box-shadow: none; color: var(--metallic-ink); }
[data-material="metallic"] [data-slot="questionnaire-choice-shortcut"] { font-family: var(--font-mono, ui-monospace, monospace); }
[data-material="metallic"] [data-slot="questionnaire-progress"] { font-family: var(--font-mono, ui-monospace, monospace); text-transform: uppercase; letter-spacing: .06em; }
